{
  "command": "git show da98f82 --stat && git show da98f82 | head -200",
  "description": "Show the last commit that turned birth-cloud dust off"
}

{
  "file_path": "/Users/liuhao/.claude/skills/liu-hao-intent/SKILL.md"
}

{
  "command": "grep -rn \"birth_cloud_dust\" --include=\"*.py\" --include=\"*.ipynb\" --include=\"*.json\" --include=\"*.md\" --include=\"*.html\" . 2>/dev/null | grep -v \"^./wiki/research/\" | cut -c1-220 | head -60",
  "description": "Find where birth_cloud_dust default is defined"
}

{
  "command": "git log --oneline -8 -- notebooks/ceridwen_integrated_photometry_spectra.ipynb; echo ---; git log --oneline -5 -- wiki/notes/model.md; echo ---; grep -rn -i \"birth.cloud\" wiki/notes/model.md wiki/index.md wiki/log.md | cut -c1-400 | head -20; echo ---; grep -rln \"birth_cloud_dust\" scripts tests ceridwen/*.py 2>/dev/null",
  "description": "Check history and other places mentioning the default"
}

{
  "command": "grep -n \"birth_cloud_dust\" scripts/calibration_arms_vast.py tests/test_dust_bump.py tests/test_ceridwen_dr2_production.py | cut -c1-240; grep -rn -i \"birth.cloud\" .agents/skills 2>/dev/null | cut -c1-240 | head",
  "description": "Check tests and scripts that reference the setting"
}

{
  "replace_all": false,
  "file_path": "/Users/liuhao/Downloads/Astro project/tmp/agent-hillclimb/sandboxes_r2/sonnet/slot0/notebooks/ceridwen_integrated_photometry_spectra.ipynb",
  "old_string": "    \"birth_cloud_dust\\\": False,  # True: power-law",
  "new_string": "    \"birth_cloud_dust\\\": True,  # True: power-law"
}

{
  "command": "git revert --no-commit da98f82 && git diff --cached --stat && git diff --cached | grep '^[+-] ' | cut -c1-120",
  "description": "Revert the dust-off commit without committing"
}

{
  "command": "python3 -m pytest tests/test_dust_bump.py tests/test_ceridwen_dr2_production.py -q 2>&1 | tail -8",
  "description": "Run the dust and production-notebook tests",
  "timeout": 300000
}

{
  "command": "ls -d .venv venv ../.venv 2>/dev/null; which -a python python3 | head; python3 -m pytest tests/test_ceridwen_dr2_production.py -q 2>&1 | tail -5",
  "description": "Look for a jax environment and run the production test alone",
  "timeout": 300000
}

{
  "command": ".venv/bin/python -m pytest tests/test_dust_bump.py tests/test_ceridwen_dr2_production.py -q 2>&1 | tail -8; git stash -q && .venv/bin/python -m pytest tests/test_ceridwen_dr2_production.py -q 2>&1 | tail -2; git stash pop -q && git status --short",
  "description": "Run tests in the project venv, compare against pre-change baseline",
  "timeout": 300000
}

{
  "command": "git -C ceridwen status --short | head; git diff --stat | tail -3",
  "description": "Check what changed in the ceridwen submodule"
}

{
  "command": "git -C ceridwen checkout -- tests/fixtures/ssp_data_bpass_agb_dust.h5; .venv/bin/python -m pytest tests/test_ceridwen_dr2_production.py -q 2>&1 | tail -2; git status --short",
  "description": "Restore test-modified fixture and rerun production tests with the change",
  "timeout": 300000
}
